import{j as n,M as O,c as M,E as l,D as m,e as u,T as h,G as p,f as g,S as v,F as y,P as E,C as c,R as f,g as S,H as C,O as b,h as t,i as A,k as i,l as w,N as P,m as k,n as _,o as T,p as $,q as I,t as q,u as L,v as U,w as x,x as B}from"./index-Cl7Vunew.js";import{g as d}from"./guildCopy-BZXBRVY9.js";import"./vendor-DDxydHEc.js";import"./vendor-sonner-BFkWhx6y.js";import"./vendor-capacitor-B8vh4tkU.js";const[,,R]=C,N=Math.round(I*c),D=k.length,H=[{icon:"❤️",en:"Hearts (HP)",pt:"Corações (HP)",descEn:"Its health. Rubbing heals it; a bad day costs at most one, and it never drops to zero out of nowhere. When a day costs nothing, the daily report says which pause held it.",descPt:"A saúde do seu Soulmon. Carinho cura; um dia ruim custa no máximo um, e nunca zera do nada. Quando um dia não custa nada, o relatório diário conta qual pausa segurou."},{icon:"⚡",en:"Energy",pt:"Energia",descEn:`The side bar. Rises with time (1 every ${l} min when well fed; slower when hungry, stopped when starving — eating fills hunger, not energy), holds twice the daily goal and resets each day. It is the Dungeon's fuel: each layer spends ${m} (up to ${u} a day), and leveling up refills it.`,descPt:`A barra lateral. Sobe com o tempo (1 a cada ${l} min com o Soulmon bem alimentado; mais devagar com fome, parada se faminto — comer enche a fome, não a energia), guarda o dobro da meta do dia e zera todo dia. É o combustível da Masmorra: cada camada gasta ${m} (até ${u} por dia), e subir de nível enche de novo.`},{icon:"🔗",en:"Bond N / Lv N",pt:"Vínculo N / Lv N",descEn:`Bond N is your level as a carer (up to ${h}); each one gives a talent point. Lv N is your Soulmon's. The Arena opens at Bond ${p.pvp.minBond}.`,descPt:`Vínculo N é o seu nível como pessoa que cuida (até ${h}); cada um rende um ponto de talento. Lv N é o do seu Soulmon. A Arena abre no Vínculo ${p.pvp.minBond}.`},{icon:"❗",en:"Missions",pt:"Missões",descEn:"One icon on Home opens Missions, with three tabs: Dailies, Weekly and Achievements. The dailies invite you to try the other places too (mini-games, focus, care). A mission only points at what to do. When you really do it, the line turns ready (a ?) and you tap Claim to receive the reward. Nothing counts tasks, and nothing is owed.",descPt:"Um ícone na Home abre as Missões, com três abas: Diárias, Semanal e Conquistas. As diárias convidam a conhecer os outros cantos (minijogos, foco, cuidado). A missão só aponta o que fazer. Quando você faz de verdade, a linha fica pronta (um ?) e você toca em Resgatar para receber. Nada conta tarefas, e nada é cobrado."},{icon:"✨",en:"Today's special",pt:"Especial do dia",descEn:`One per day. With a step counter it alternates between walking ${g.toLocaleString("en-US")} steps (you choose the goal; a change starts the next day) and lying down within your rest window; without one it is always the rest window. It counts like ${v} daily habit toward evolution, does not affect the complete-day seal or hearts, and skipping it costs nothing.`,descPt:`Uma por dia. Com contador de passos, alterna entre caminhar ${g.toLocaleString("pt-BR")} passos (você escolhe a meta; a troca vale a partir do dia seguinte) e deitar dentro da sua janela de descanso; sem contador, é sempre a janela de descanso. Vale como ${v} hábito diário na evolução, não mexe no selo de dia completo nem nos corações, e deixar para lá não custa nada.`},{icon:"🎖️",en:"Talents & equipment",pt:"Talentos e equipamento",descEn:`Talents (three paths) live in the Bond Sanctum — open the tree to see what it gives now, already added to your equipment; the three equipment slots are at the Soulsmith in the Market. Pieces come from building missions (level 1) and are parts of your soul, refined there with mission materials, choosing one of two gains per level (up to level ${y}). Together they add at most ${Math.round(T*100)}% strength; never drawn, never bought with money.`,descPt:`Os talentos (três caminhos) ficam no Santuário do Vínculo — abra a árvore para ver o que ela dá agora, já somado ao equipamento; os três espaços de equipamento, no Soulsmith, no Mercado. As peças vêm das missões dos prédios (nível 1) e são partes da sua alma, aprimoradas lá com os materiais, escolhendo um de dois ganhos por nível (até o nível ${y}). Juntos somam no máximo ${Math.round(T*100)}% de força; nunca sorteado, nunca comprado com dinheiro.`},{icon:"🍽️",en:"Meal check-ins",pt:"Convites das refeições",descEn:`After breakfast, lunch and dinner your Soulmon may ask for one small thing — a pat, a rinse, a snack — for ${$/60} hours. No points, no count; skipping is free. Reminders are off until you turn them on in Settings (up to ${E} a day, never in your rest window).`,descPt:`Depois do café, do almoço e do jantar, seu Soulmon pode pedir uma coisa pequena — um carinho, um banho, uma comidinha — por ${$/60} horas. Sem pontos, sem contagem; pular não custa nada. Os lembretes ficam desligados até você ligar nas Configurações (no máximo ${E} por dia, nunca na sua janela de descanso).`},{icon:"🥚",en:"Rebirth",pt:"Renascimento",descEn:"After the Ultra: your creature becomes an egg and you choose who they come back as. Once per creature.",descPt:"Depois do Ultra: sua criatura vira ovo e você escolhe quem ela volta a ser. Uma vez por criatura."},{icon:"🧬",en:"Soul Fragments",pt:"Fragmentos de Alma",descEn:"The evolution currency. Every habit or task you finish earns Soul Fragments (bigger tasks earn more), up to your stage’s daily goal per day. They join at the turn of the day, never shrink, and when you have gathered enough they are used and the next form opens.",descPt:"A moeda da evolução. Todo hábito ou tarefa concluída rende Fragmentos de Alma (tarefas maiores rendem mais), até a meta diária do estágio por dia. Entram na virada do dia, nunca diminuem, e quando você junta o bastante são usados e a próxima forma abre."},{icon:"📊",en:"Complete Day",pt:"Dia Completo",descEn:"The whole daily goal done. A seal for the day that pays Bits — it no longer decides evolution (the path does).",descPt:"A meta do dia inteira feita. Um selo do dia que rende Bits — não decide mais a evolução (quem decide é o caminho)."},{icon:"👊",en:"Power / 🎶 Harmony / 🤲 Benevolence",pt:"Poder / 🎶 Harmonia / 🤲 Benevolência",descEn:"Attribute points from feeding. The dominant one picks which branch it evolves into.",descPt:"Pontos de atributo ganhos alimentando. O dominante define o galho da evolução."},{icon:"🥚",en:"Incubation",pt:"Incubação",descEn:"When the bar fills, the next form starts taking shape — it takes a while. Come back whenever you like: it waits for you, and nothing is lost.",descPt:"Quando a barra enche, a próxima forma começa a tomar corpo — leva um tempo. Volte quando quiser: ela espera por você, e nada se perde."},{icon:"🔒",en:"Evolution padlock",pt:"Cadeado de evolução",descEn:"Tap your current Soulmon on the Evolution page. Locked, it never evolves — the path keeps adding up.",descPt:"Toque no seu Soulmon atual na página de Evolução. Travado, seu Soulmon nunca evolui — o caminho segue somando."},{icon:"🌀",en:"Glitchtama",pt:"Glitchtama",descEn:"Rare item from the first milestone (every 5 layers) of each automatic dungeon descent. Using it adds one day’s worth of steps to the evolution path — one a day, so the ladder stays measured in days.",descPt:"Item raro do primeiro marco (a cada 5 camadas) de cada descida automática da masmorra. Usar soma um dia de passos ao caminho da evolução — um por dia, para a escada continuar sendo medida em dias."},{icon:"🧭",en:"Stroll & Crossings",pt:"Passeio e Travessias",descEn:"In Exploration: pick where your Soulmon strolls each day. Crossings are optional things you do in your own life that clear the mist over a new region — no deadline, and they never touch your pet or the daily goal.",descPt:"Na Exploração: escolha para onde seu Soulmon passeia cada dia. Travessias são coisas opcionais que você faz na sua vida e abrem a névoa de uma região nova — sem prazo, e nunca mexem no seu Soulmon nem na meta do dia."},{icon:"💗",en:"Little Heart",pt:"Coraçãozinho",descEn:"Shop item and rare dungeon drop. Using it from the Backpack heals 1 HP.",descPt:"Item da loja e drop raro da masmorra. Usar pela mochila cura 1 HP."},{icon:"📈",en:"Consistency",pt:"Constância",descEn:`Replaces the streak: "${N} of the last ${c}". Nothing here resets to zero.`,descPt:`Substitui a sequência: "${N} das últimas ${c}". Nada aqui volta para zero.`},{icon:"🛡️",en:"Rest shield",pt:"Escudo de descanso",descEn:`Earned every ${f} days of good consistency (up to ${S}), and spent automatically on a day you miss.`,descPt:`Ganho a cada ${f} dias de boa constância (até ${S}), e gasto sozinho no dia em que você falta.`},{icon:"🌳",en:"Habit maturity",pt:"Maturidade do hábito",descEn:`Seed → Sprout → Sapling → Tree. The icon grows and the habit yields more attribute, up to ${R} days done.`,descPt:`Semente → Broto → Muda → Árvore. O ícone cresce e o hábito rende mais atributo, até ${R} dias feitos.`},{icon:"🏋️",en:"Effort",pt:"Esforço",descEn:`Quick (1), Medium (2), Project (3). The goal adds up effort, not items; past ${b} in a day it's a heads-up, never a block.`,descPt:`Rápida (1), Média (2), Projeto (3). A meta soma esforço, não itens; passando de ${b} no dia é aviso, nunca bloqueio.`},{icon:"⭐",en:"Premium food",pt:"Comida premium",descEn:"Earned by finishing every step of a task with 3 or more steps. Fills your Soulmon's hunger (it does not give energy directly). One a day, three a week.",descPt:"Vem de fechar todos os subitens de uma tarefa com 3 ou mais. Enche a fome do Soulmon (não dá energia direto). Uma por dia, três por semana."},{icon:"🎯",en:"Today's focus",pt:"Foco do dia",descEn:`Up to ${t} tasks chosen at check-in. Completing all ${t} earns the day's seal.`,descPt:`Até ${t} tarefas escolhidas no check-in. Completar as ${t} rende o selo do dia.`},{icon:"👻",en:"Haunted",pt:"Assombrada",descEn:`Overdue or untouched for ${A} days. Clearing one pays a relief bonus — it is not a scolding.`,descPt:`Vencida ou parada há ${A} dias. Concluir uma dá bônus de alívio — não é bronca.`},{icon:"💤",en:"Someday",pt:"Algum dia",descEn:"A deliberately inert list: out of the goal, never ages, never haunts. And it comes back whenever you want.",descPt:"Uma lista deliberadamente parada: fora da meta, não envelhece, não assombra. E volta quando você quiser."},{icon:"🌙",en:"Let it go",pt:"Deixar pra lá",descEn:"An honest ending for a task that will not happen — with its own list and an undo.",descPt:"Um fim honesto para a tarefa que não vai acontecer — com lista própria e volta atrás."},{icon:"🛏️",en:"Rest Window",pt:"Janela de Descanso",descEn:`The sleep window you choose (default ${i.start}–${i.end}). Read as "how many of the last ${w} nights" — no score, no penalty. A night on time brings ${P} extra energy in the morning, once a day.`,descPt:`A janela de sono que você escolhe (padrão ${i.start}–${i.end}). Lida como "quantas das últimas ${w} noites" — sem nota, sem castigo. Uma noite no horário traz ${P} de energia a mais de manhã, uma vez por dia.`},{icon:"🌠",en:"Dream",pt:"Sonho",descEn:`A collectible scene of your Soulmon, one per night inside the window. ${D} to discover.`,descPt:`Uma cena colecionável do seu Soulmon, uma por noite dentro da janela. São ${D} para descobrir.`},{icon:"💠",en:"Bits vs. 🎖️ Honor vs. 💎 Credits",pt:"Bits vs. 🎖️ Honra vs. 💎 Créditos",descEn:"Bits come from minigames and buy the shop. Honor comes from the Tournament and buys cosmetics only. Credits are bought with real money.",descPt:"Bits vêm dos minijogos e compram a loja. Honra vem do Torneio e compra só cosméticos. Créditos são comprados com dinheiro real."},{icon:"🧪",en:"Demo",pt:"Demo",descEn:`Try the game without an account at Bond ${_}. Saved on this device only; no XP, no purchases, no PvP.`,descPt:`Experimente o jogo sem conta, no Vínculo ${_}. Salva só neste aparelho; sem XP, sem compras, sem PvP.`},...j()];function j(){const e=(r,s,o,a)=>({icon:r,en:d("en-US",s),pt:d("pt-BR",s),descEn:d("en-US",o,a),descPt:d("pt-BR",o,a)});return[e("🌳","guild.help.guilda.termo","guild.help.guilda.def",{max:q}),e("🌳","guild.help.bosque.termo","guild.help.bosque.def"),e("🌳","guild.help.fio.termo","guild.help.fio.def"),e("🌳","guild.help.feira.termo","guild.help.feira.def",{cheio:U,piso:L}),e("🌳","guild.help.casa.termo","guild.help.casa.def"),e("🌳","guild.help.missao.termo","guild.help.missao.def"),e("🌳","guild.help.guerra.termo","guild.help.guerra.def"),e("🌳","guild.help.mare.termo","guild.help.mare.def",{semanas:x}),e("🌳","guild.help.concha.termo","guild.help.concha.def",{n:B})]}function V({isOpen:e,onClose:r,language:s}){const o=s==="pt-BR";return n.jsxs(O,{open:e,onClose:r,language:s,title:o?"Glossário":"Glossary",maxWidth:520,children:[n.jsx("p",{style:M,children:o?"O que cada palavra da tela quer dizer. O Soulmon tem um universo próprio: estes são os nomes dele, e nenhum deles descreve você.":"What each word on screen means. Soulmon has a world of its own: these are its names, and none of them describe you."}),n.jsx("dl",{className:"sm2-conta-gl",children:H.map(a=>n.jsxs("div",{children:[n.jsx("dt",{children:o?a.pt:a.en}),n.jsx("dd",{children:o?a.descPt:a.descEn})]},a.en))})]})}export{V as HelpModal};
